func newShipcheckLocalCmd(flags *rootFlags) *cobra.Command {
	var mcpBinary string
	cmd := &cobra.Command{
		Use:   "local",
		Short: "Run local public-preview readiness checks",
		Long: `Run local public-preview readiness checks.

This verifier inspects the in-process CLI command tree, local workflow plan names, local docs command-search indexing, and optional local stdio MCP tools/list. It does not call Straddle APIs, docs endpoints, GitHub, npm, Homebrew, publish, sign, notarize, read secrets, or write production.`,
		Example: `  straddle-pp-cli shipcheck local
  straddle-pp-cli shipcheck local --json
  straddle-pp-cli shipcheck local --mcp-binary ./bin/straddle-pp-mcp --agent`,
		Annotations: map[string]string{
			"mcp:read-only":              "true",
			localOnlyNoPreloadAnnotation: "true",
		},
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if flags.deliverSpec != "" {
				return usageErr(fmt.Errorf("shipcheck local does not support --deliver; use normal stdout, JSON, or agent output"))
			}
			payload, checkErr := buildShipcheckLocalResponse(cmd.Root(), mcpBinary)
			if renderErr := renderShipcheckLocalResponse(cmd, flags, payload); renderErr != nil {
				return renderErr
			}
			if checkErr != nil {
				return checkErr
			}
			if !payload.Passed {
				return apiErr(fmt.Errorf("shipcheck local failed"))
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&mcpBinary, "mcp-binary", "", "Optional path or command name for a local stdio straddle-pp-mcp binary to verify with initialize plus tools/list")
	return cmd
}

func buildShipcheckLocalResponse(root *cobra.Command, mcpBinary string) (shipcheckLocalResponse, error) {
	payload := shipcheckLocalResponse{
		Command: "shipcheck local",
		Safety:  defaultShipcheckSafety(strings.TrimSpace(mcpBinary) != ""),
	}
	payload.Checks = append(payload.Checks,
		checkShipcheckCommandTree(root),
		checkShipcheckWorkflowPlans(),
		checkShipcheckDocsCommandSearch(),
		checkShipcheckSafetyContract(),
	)

	var firstErr error
	if strings.TrimSpace(mcpBinary) != "" {
		check, err := checkShipcheckMCPTools(root, mcpBinary)
		payload.Checks = append(payload.Checks, check)
		if err != nil {
			firstErr = err
		}
	}

	payload.Passed = true
	for _, check := range payload.Checks {
		if !check.Passed {
			payload.Passed = false
			if firstErr == nil {
				firstErr = apiErr(fmt.Errorf("shipcheck local failed check %q: %s", check.Name, check.Note))
			}
		}
	}
	return payload, firstErr
}

