func checkShipcheckMCPTools(root *cobra.Command, binary string) (shipcheckCheck, error) {
	check := shipcheckCheck{
		Name: "mcp_tools",
		Note: "local stdio MCP initialize plus tools/list only",
	}
	validated, err := validateSmokeMCPBinary(binary)
	if err != nil {
		check.Note = err.Error()
		return check, err
	}

	ctx := context.Background()
	if root != nil {
		ctx = root.Context()
	}
	tools, err := runLocalMCPToolsList(ctx, validated, "straddle-pp-cli-shipcheck")
	if err != nil {
		check.Note = err.Error()
		return check, err
	}
	missing := missingShipcheckMCPTools(tools)
	if len(missing) > 0 {
		check.Note = "local stdio MCP tools/list missing required tool(s): " + strings.Join(missing, ", ")
		check.Evidence = sortedKeys(tools)
		return check, apiErr(fmt.Errorf("MCP tools/list missing required tool(s): %s", strings.Join(missing, ", ")))
	}
	check.Passed = true
	check.Evidence = requiredShipcheckMCPTools()
	return check, nil
}

func runLocalMCPToolsList(ctx context.Context, binary string, clientName string) (map[string]bool, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	var cancel context.CancelFunc
	ctx, cancel = context.WithTimeout(ctx, 30*time.Second)
	defer cancel()

	process := exec.CommandContext(ctx, binary)
	process.Env = smokeMCPProcessEnv()

	stdin, err := process.StdinPipe()
	if err != nil {
		return nil, usageErr(fmt.Errorf("prepare MCP stdin: %w", err))
	}
	stdout, err := process.StdoutPipe()
	if err != nil {
		return nil, usageErr(fmt.Errorf("prepare MCP stdout: %w", err))
	}
	if err := process.Start(); err != nil {
		return nil, usageErr(fmt.Errorf("start MCP binary: %w", err))
	}
	defer func() {
		_ = process.Process.Kill()
		_ = process.Wait()
	}()

	scanner := bufio.NewScanner(stdout)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	encoder := json.NewEncoder(stdin)

	if err := encoder.Encode(map[string]any{
		"jsonrpc": "2.0",
		"id":      1,
		"method":  "initialize",
		"params": map[string]any{
			"protocolVersion": "2024-11-05",
			"capabilities":    map[string]any{},
			"clientInfo": map[string]string{
				"name":    clientName,
				"version": "0",
			},
		},
	}); err != nil {
		return nil, apiErr(fmt.Errorf("write MCP initialize request: %w", err))
	}
	if _, err := readSmokeMCPResponse(scanner, "1"); err != nil {
		return nil, err
	}
	if err := encoder.Encode(map[string]any{
		"jsonrpc": "2.0",
		"method":  "notifications/initialized",
		"params":  map[string]any{},
	}); err != nil {
		return nil, apiErr(fmt.Errorf("write MCP initialized notification: %w", err))
	}
	if err := encoder.Encode(map[string]any{
		"jsonrpc": "2.0",
		"id":      2,
		"method":  "tools/list",
		"params":  map[string]any{},
	}); err != nil {
		return nil, apiErr(fmt.Errorf("write MCP tools/list request: %w", err))
	}
	response, err := readSmokeMCPResponse(scanner, "2")
	if err != nil {
		return nil, err
	}
	return smokeMCPToolNames(response), nil
}

