func missingShipcheckMCPTools(tools map[string]bool) []string {
	var missing []string
	for _, name := range requiredShipcheckMCPTools() {
		if !tools[name] {
			missing = append(missing, name)
		}
	}
	return missing
}

func sortedKeys(values map[string]bool) []string {
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

func renderShipcheckLocalResponse(cmd *cobra.Command, flags *rootFlags, payload shipcheckLocalResponse) error {
	asJSON := flags.asJSON || flags.agent || !isTerminal(cmd.OutOrStdout())
	if asJSON {
		return printJSONFiltered(cmd.OutOrStdout(), payload, flags)
	}
	w := cmd.OutOrStdout()
	status := "failed"
	if payload.Passed {
		status = "passed"
	}
	fmt.Fprintf(w, "Shipcheck local: %s\n", status)
	for _, check := range payload.Checks {
		checkStatus := "failed"
		if check.Passed {
			checkStatus = "passed"
		}
		fmt.Fprintf(w, "  %s: %s", check.Name, checkStatus)
		if check.Note != "" {
			fmt.Fprintf(w, " - %s", check.Note)
		}
		fmt.Fprintln(w)
	}
	return nil
}
